"use strict";
// AUTO-GENERATED by extract_core.js - do not edit. Source of truth:
// hip3_strat_screener.html between STRAT-CORE-BEGIN / STRAT-CORE-END.
// ==== STRAT-CORE-BEGIN ====
// Pure STRAT logic. No DOM, no state. Testable standalone.

function classify(h, l, ph, pl){
  var bh = h > ph, bl = l < pl;            // strict inequality per STRAT
  if(bh && bl) return "3";
  if(bh) return "2U";
  if(bl) return "2D";
  return "1";
}

function classifySeries(closed){
  var types = new Array(closed.length).fill(null);
  for(var i=1;i<closed.length;i++)
    types[i] = classify(closed[i].h, closed[i].l, closed[i-1].h, closed[i-1].l);
  return types;
}

// Completed pattern ending at the LAST CLOSED bar (informational).
// closed is needed to color-route 3-1-2: a Type 3 bar's direction is its
// close color (green = bullish, red = bearish); a 3-1-2 in the SAME
// direction as the 3's color is a continuation, not a reversal - the
// digits alone never decide it.
function detectCompleted(types, closed){
  var n = types.length;
  if(n < 2) return null;
  var tL = types[n-1], tP = types[n-2], tQ = n>=3 ? types[n-3] : null;
  var m3 = {
    "3,1,2U":"3-1-2U","3,1,2D":"3-1-2D",
    "2D,1,2U":"2D-1-2U","2U,1,2D":"2U-1-2D",
    "2U,1,2U":"2U-1-2U","2D,1,2D":"2D-1-2D",
    "3,2D,2U":"3-2D-2U","3,2U,2D":"3-2U-2D"
  };
  var m2 = {"2D,2U":"2D-2U","2U,2D":"2U-2D","3,2U":"3-2U","3,2D":"3-2D"};
  // 1-2-2 Rev Strat completed forms: inside bar, trap 2, reversal 2.
  m3["1,2D,2U"] = "1-2-2";
  m3["1,2U,2D"] = "1-2-2";
  var k3 = [tQ,tP,tL].join(",");
  if(tQ && m3[k3]){
    var cont = k3==="2U,1,2U" || k3==="2D,1,2D";
    if((k3==="3,1,2U" || k3==="3,1,2D") && closed && closed.length >= 3){
      var b0 = closed[closed.length-3];
      if(k3==="3,1,2U" && b0.c > b0.o) cont = true;   // green 3 -> same-direction 2U
      if(k3==="3,1,2D" && b0.c < b0.o) cont = true;   // red 3 -> same-direction 2D
    }
    return {name:m3[k3], dir: tL==="2U"?"up":"down", cont:cont};
  }
  var k2 = [tP,tL].join(",");
  if(tP && m2[k2]) return {name:m2[k2], dir: tL==="2U"?"up":"down", cont:false};
  return null;
}

// Target rules v2 (design decisions 2026-09-22/23 + 2026-10-31).
// v1 = the k=2 swing pivot
// plus a 1.5 x stop-distance projection, which served targets below zero.
function targetVersion(){ return 2; }

// The FIRST PRIOR LEVEL NOT YET TAKEN OUT beyond the trigger, judged on
// FINISHED bars only (the forming bar never moves a target): walk the
// signal timeframe's bars newest first, then the finished 1h bars before
// them (the bridge: a 15m/30m window starts inside a day whose daily bar is
// still forming), then the daily bars before those. A level is taken out
// only by a strict break (R10), so a high stands while no later high
// exceeds it. Returns {px, src, i} or null.
function levelTarget(closed, dir, trigger, ctx){
  var up = dir === "up", run = up ? -Infinity : Infinity;
  var start = closed.length ? closed[0].t : Infinity;   // the oldest instant searched so far
  function walk(bars, src, older){
    for(var i = bars.length - 1; i >= 0; i--){
      if(older && bars[i].t >= start) continue;      // already covered by finer bars
      var v = up ? bars[i].h : bars[i].l;
      if(up ? (v >= run && v > trigger) : (v <= run && v < trigger)) return {px:v, src:src, i:i};
      run = up ? Math.max(run, v) : Math.min(run, v);
    }
    return null;
  }
  var r = walk(closed, "tf", false);
  if(r) return r;
  if(ctx && ctx.bridge){
    if((r = walk(ctx.bridge, "bridge", true))) return r;
    if(ctx.bridge.length && ctx.bridge[0].t < start) start = ctx.bridge[0].t;
  }
  if(ctx && ctx.daily) return walk(ctx.daily, "daily", true);
  return null;
}

// PMG (Pivot Machine Gun) run length: count CONSECUTIVE strictly lower highs
// ("lh", a bearish run -> bullish reversal) or strictly higher lows ("hl", a
// bullish run -> bearish reversal) ending AT the last closed bar. Walk backward
// from the last bar, stop at the first bar that breaks the chain (cheap; O(run
// length)). The caller thresholds at >= 5. The reference bar
// (index 0) has no type but its wick extremes are real, so it counts.
function pmgRun(closed, side){
  var count = 0;
  for(var i = closed.length - 1; i >= 1; i--){
    if(side === "lh"){ if(closed[i].h < closed[i-1].h) count++; else break; }
    else            { if(closed[i].l > closed[i-1].l) count++; else break; }
  }
  return count;
}

// MoMo hammer / shooter SHAPE on the last closed bar. DISPLAY-TIER
// ONLY - never a live entry: the methodology requires higher-TF continuity in
// the trade direction, which the dashboard gates visually with the FTFC dots,
// not here. Pelonsax defaults (all five configurable):
var MOMO_LEN = 30;      // avg-body lookback (closed bars)
var MOMO_MIN = 10;      // fewer closed bars than this -> no shape
var MOMO_BODY = 0.30;   // signal body <= this * avg body
var MOMO_SHADOW = 2.0;  // dominant wick > this * signal body
var MOMO_ERR = 0.25;    // opposite wick <= this * avg body
// Returns null | {type:"hammer"|"shooter", confirming:bool}. confirming = the
// forming bar's current close is ALREADY beyond the signal bar's extreme
// (hammer: forming.c > sig.h; shooter: forming.c < sig.l). "confirming" not
// "confirmed" - the forming bar has not closed yet (confirm = the NEXT
// bar CLOSES beyond). A zero-body (doji) signal bar floors its body at 1e-12
// so the dominant-wick test still fires on any real wick; the opposite-wick
// and prior-3-close trend filters keep it honest. avgBody includes the signal
// bar (ThinkScript Average convention). The 3 prior closes are the bars right
// before the signal (MOMO_MIN >= 4 guarantees they exist).
function momoShape(closed, forming){
  var n = closed.length;
  if(n < MOMO_MIN) return null;
  var sig = closed[n-1];
  var lookback = Math.min(MOMO_LEN, n), sum = 0;
  for(var i = n - lookback; i < n; i++) sum += Math.abs(closed[i].c - closed[i].o);
  var avgBody = sum / lookback;
  var body = Math.abs(sig.c - sig.o);
  if(body > MOMO_BODY * avgBody) return null;                 // body not small enough
  var bodyEff = body > 1e-12 ? body : 1e-12;
  var upper = sig.h - Math.max(sig.o, sig.c);
  var lower = Math.min(sig.o, sig.c) - sig.l;
  var c1 = closed[n-2].c, c2 = closed[n-3].c, c3 = closed[n-4].c; // 3 closes before signal
  var asc  = c3 < c2 && c2 < c1;                              // strictly ascending -> hammer
  var desc = c3 > c2 && c2 > c1;                              // strictly descending -> shooter
  var type = null;
  if(lower > MOMO_SHADOW * bodyEff && upper <= MOMO_ERR * avgBody && asc) type = "hammer";
  else if(upper > MOMO_SHADOW * bodyEff && lower <= MOMO_ERR * avgBody && desc) type = "shooter";
  if(!type) return null;
  var confirming = false;
  if(forming) confirming = type === "hammer" ? forming.c > sig.h : forming.c < sig.l;
  return {type:type, confirming:confirming};
}

// Full per-timeframe analysis.
// closed: array of {t,o,h,l,c} CLOSED bars ascending. forming: {t,o,h,l,c} or null.
// firstBreak (optional): which side of the LAST CLOSED bar's range the forming
//   bar broke FIRST ("up" | "down" | null). Callers track it tick-by-tick;
//   null = unknown order (e.g. first sight of an already-outside bar). It only
//   feeds the 1-3 Rev Strat, which is path-dependent by definition.
// Returns types, forming classification, completed pattern, setups (pending triggers)
// and live (forming bar already broke a trigger -> pattern in force NOW).
// ctx (optional): {daily: closed daily bars oldest first, complete: the
// daily bars are the coin's ENTIRE history} - the level search's second
// source and the all-time-extreme test (target rules v2).
function analyzeTF(closed, forming, firstBreak, ctx){
  var res = {types:[], formingType:null, formingDir:null,
             completed:null, setups:[], live:[], invalidated:false, shape:null};
  var n = closed.length;
  res.types = classifySeries(closed);
  if(n < 2) return res;

  var L = closed[n-1], P = closed[n-2];
  var tL = res.types[n-1], tP = res.types[n-2];

  if(forming){
    res.formingType = classify(forming.h, forming.l, L.h, L.l);
    res.formingDir  = forming.c > forming.o ? "up" : (forming.c < forming.o ? "down" : "flat");
  }
  res.completed = detectCompleted(res.types, closed);

  // tgt_rule: which rule produced the target - "structural" (a wick of the
  // pattern's own bars), "level" (a prior level), "fallback" (entry +/- 1.5%)
  // or "none" (no target). Default: a fixed wick target, or none when null.
  function add(name, dir, trigger, stop, target, kind, rule){
    res.setups.push({name:name, dir:dir, trigger:trigger, stop:stop, target:target, kind:kind,
                     tgt_rule: rule || (target === null ? "none" : "structural")});
  }

  // Target for the continuations (bar0: true - the 3's / bar 0's far extreme
  // is the walk's first candidate, so "unless already traded through, the
  // first prior level not yet taken out" is the same search) and the 3-2
  // (no structural magnitude). Nothing beyond the trigger: an all-time
  // extreme -> no target, when the daily history is the coin's whole
  // history; otherwise the history is short and the fallback is entry +/-
  // 1.5% (design decision 2026-09-23: "always 1.5 percent away from entry").
  function resolve(dir, trigger, bar0){
    var r = levelTarget(closed, dir, trigger, ctx);
    if(r) return {t:r.px, rule:(bar0 && r.src === "tf" && r.i === n - 2) ? "structural" : "level"};
    if(ctx && ctx.daily && ctx.complete === true) return {t:null, rule:"none"};
    return {t:dir === "up" ? trigger * 1.015 : trigger * 0.985, rule:"fallback"};
  }
  function addResolved(name, dir, trigger, stop, kind, bar0){
    var r = resolve(dir, trigger, bar0);
    add(name, dir, trigger, stop, r.t, kind, r.rule);
  }

  // Setups: what CAN complete on the forming bar, with trigger/stop/target.
  // kind: "rev" = active entry signal, "cont" = continuation (info, not fresh entry),
  //       "info" = structure without a valid reference.
  if(tL === "1"){
    var base = tP || "?";
    // Type 3 reference bar: direction = close color (green bullish, red
    // bearish - the digits alone never decide). A break in the SAME direction
    // as the 3's color is a CONTINUATION (target via resolve: the 3's far
    // extreme first; exit on a reversal combo); opposite color = reversal
    // with the 3's wick as target. A dead-even close (c === o) stays
    // reversal-eligible: the break decides.
    var p3green = tP === "3" && P.c > P.o;
    var p3red   = tP === "3" && P.c < P.o;
    // upside break of the inside bar
    if(p3green)          addResolved("3-1-2U","up", L.h, P.l, "cont", true);
    else if(tP === "3")  add("3-1-2U","up",       L.h, P.l, P.h, "rev");
    else if(tP === "2D") add(base+"-1-2U","up",   L.h, P.l, P.h, "rev");
    else if(tP === "2U") addResolved(base+"-1-2U","up", L.h, Math.min(P.l,L.l), "cont", true);
    else if(tP === "1")  add("1-1-2U","up",       L.h, L.l, null, "info");   // mother bar territory
    else                 add("?-1-2U","up",       L.h, L.l, null, "info");
    // downside break of the inside bar
    if(p3red)            addResolved("3-1-2D","down", L.l, P.h, "cont", true);
    else if(tP === "3")  add("3-1-2D","down",     L.l, P.h, P.l, "rev");
    else if(tP === "2U") add(base+"-1-2D","down", L.l, P.h, P.l, "rev");
    else if(tP === "2D") addResolved(base+"-1-2D","down", L.l, Math.max(P.h,L.h), "cont", true);
    else if(tP === "1")  add("1-1-2D","down",     L.l, L.h, null, "info");
    else                 add("?-1-2D","down",     L.l, L.h, null, "info");
  } else if(tL === "2D"){
    if(tP === "3")                      add("3-2D-2U","up", L.h, Math.min(P.l,L.l), P.h, "rev");
    else if(tP === "2U" || tP === "2D") add("2D-2U","up",   L.h, L.l, P.h, "rev");
    // reference-bar router: a 1 before the 2-2 makes it a 1-2-2 Rev Strat -
    // the 2D is the TRAP bar (it broke the inside bar's low), the reversal
    // fires through the trap's high, target = bar 0's wick (the bar the
    // inside bar sits inside; classification guarantees containment).
    else if(tP === "1" && n >= 3)       add("1-2-2","up",   L.h, L.l, closed[n-3].h, "rev");
    // 2D-2D continuation is position management, not an entry - omitted by design
  } else if(tL === "2U"){
    if(tP === "3")                      add("3-2U-2D","down", L.l, Math.max(P.h,L.h), P.l, "rev");
    else if(tP === "2U" || tP === "2D") add("2U-2D","down",   L.l, L.h, P.l, "rev");
    else if(tP === "1" && n >= 3)       add("1-2-2","down",   L.l, L.h, closed[n-3].l, "rev");
  } else if(tL === "3"){
    // 3-2 has NO structural magnitude (the 3's extreme IS the trigger): the
    // first prior level not yet taken out beyond it (the ladder rule, T1).
    addResolved("3-2U","up",   L.h, L.l, "rev", false);
    addResolved("3-2D","down", L.l, L.h, "rev", false);
  }

  // PMG (Pivot Machine Gun): a run of >= 5 consecutive strictly lower highs
  // (bullish reversal) or higher lows (bearish reversal) ending at the last
  // closed bar. COEXISTS with the setups above (do not suppress either) and is
  // emitted regardless of tL EXCEPT when the last closed bar is a Type 3 - the
  // 3-2 branch owns that structure. Trigger = the last bar's broken rung (its
  // H for the lower-high run / L for the higher-low run); target = the previous
  // chain rung (P.h / P.l) - the pivot ladder walked pivot-to-pivot.
  if(tL !== "3"){
    if(pmgRun(closed, "lh") >= 5) add("PMG","up",   L.h, L.l, P.h, "rev", "level");
    if(pmgRun(closed, "hl") >= 5) add("PMG","down", L.l, L.h, P.l, "rev", "level");
  }

  // LIVE: forming bar already broke a trigger. Monotonic - cannot untrigger.
  if(forming){
    for(var i=0;i<res.setups.length;i++){
      var s = res.setups[i];
      var hit = s.dir === "up" ? forming.h > s.trigger : forming.l < s.trigger;
      if(hit && s.kind !== "info") res.live.push({name:s.name, dir:s.dir, entry:s.trigger,
                                                  stop:s.stop, target:s.target, kind:s.kind, tgt_rule:s.tgt_rule});
    }
    if(res.formingType === "3" && res.live.length) res.invalidated = true; // went outside
    // 1-3 Rev Strat: after an inside bar, the entry bar takes one side FIRST
    // then breaks the other - a compound 3. The SECOND break is a first-class
    // reversal entry: target = bar 0's wick (the bar the inside bar sits
    // inside), stop = the inside bar's opposite extreme. Path-dependent:
    // firstBreak comes from the caller's tick-by-tick tracking; null (order
    // unknown, e.g. first sight of an already-outside bar) emits nothing.
    // rev3 marks it born ON the 3 - consumers exempt it from the
    // invalidation above (the invalidation IS this signal's birth event).
    if(tL === "1" && res.formingType === "3"){
      if(firstBreak === "down")
        res.live.push({name:"1-3", dir:"up",   entry:L.h, stop:L.l, target:P.h, kind:"rev", rev3:true, tgt_rule:"structural"});
      else if(firstBreak === "up")
        res.live.push({name:"1-3", dir:"down", entry:L.l, stop:L.h, target:P.l, kind:"rev", rev3:true, tgt_rule:"structural"});
    }
  }

  // MoMo hammer / shooter SHAPE on the last closed bar (display-tier; never a
  // live entry - see momoShape). null when no shape or too few bars.
  res.shape = momoShape(closed, forming);
  return res;
}

// ---- Calendar aggregation (W/M derived from daily bars) ----
// Hyperliquid's native 1w/1M candles are epoch-aligned 7-day / 30-day buckets
// (Thursday weeks, drifting months). STRAT wants true calendar bars, so weekly
// and monthly are aggregated client-side from daily candles instead.

function weekStart(t){                       // Monday 00:00 UTC
  var dse = Math.floor(t / 86400000);
  var wd = (dse + 4) % 7;                    // 0=Sun .. 6=Sat (epoch day was a Thursday)
  return (dse - ((wd + 6) % 7)) * 86400000;
}
function monthStart(t){
  var d = new Date(t);
  return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), 1);
}
function nextMonthStart(t){
  var d = new Date(t);
  return Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 1);
}
// bars: daily candles ascending (forming daily may be included as last element).
// mode: "week" | "month". Drops a partial first bucket so H/L are never understated.
function aggregateBars(bars, mode){
  var out = [];
  for(var i=0;i<bars.length;i++){
    var x = bars[i];
    var k = mode === "week" ? weekStart(x.t) : monthStart(x.t);
    var last = out[out.length-1];
    if(!last || last.t !== k){
      out.push({t:k, T:(mode === "week" ? k + 604800000 : nextMonthStart(k)) - 1,
                o:x.o, h:x.h, l:x.l, c:x.c});
    } else {
      if(x.h > last.h) last.h = x.h;
      if(x.l < last.l) last.l = x.l;
      last.c = x.c;
    }
  }
  if(out.length && bars.length && bars[0].t > out[0].t) out.shift();
  return out;
}
// ==== STRAT-CORE-END ====

module.exports = {
  classify: classify,
  classifySeries: classifySeries,
  detectCompleted: detectCompleted,
  analyzeTF: analyzeTF,
  weekStart: weekStart,
  monthStart: monthStart,
  nextMonthStart: nextMonthStart,
  aggregateBars: aggregateBars,
  targetVersion: targetVersion
};
